package com.rohit.inventory.entity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="alerts") public class Alert extends BaseEntity { @Column(name="alert_type",nullable=false) private String alertType; @Enumerated(EnumType.STRING) @Column(nullable=false) private Severity severity; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id") private Warehouse warehouse; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id") private Product product; @Column(nullable=false) private String title; @Column(nullable=false) private String message; @Column(nullable=false) private String status="ACTIVE"; @Column(name="resolved_at") private Instant resolvedAt; public enum Severity{INFO,SUCCESS,WARNING,CRITICAL} public UUID getId(){return super.getId();} public String getAlertType(){return alertType;} public Severity getSeverity(){return severity;} public Warehouse getWarehouse(){return warehouse;} public Product getProduct(){return product;} public String getTitle(){return title;} public String getMessage(){return message;} public String getStatus(){return status;} public Instant getCreatedAt(){return super.getCreatedAt();} public void setAlertType(String v){alertType=v;} public void setSeverity(Severity v){severity=v;} public void setWarehouse(Warehouse v){warehouse=v;} public void setProduct(Product v){product=v;} public void setTitle(String v){title=v;} public void setMessage(String v){message=v;} public void setStatus(String v){status=v;} public void setResolvedAt(Instant v){resolvedAt=v;} }
